"use client";
import Link from "next/link";
import { useState } from "react";
const links = [["الرئيسية", "/"], ["من نحن", "/about"], ["خدماتنا", "/services"], ["مشاريعنا", "/projects"]] as const;
export function Navbar() { const [open,setOpen]=useState(false); return <header className="sticky top-0 z-50 border-b border-black/10 bg-[#f4f1ea]/95 backdrop-blur"><div className="container flex h-18 items-center justify-between py-4"><Link href="/" className="font-bold leading-tight">دار البناء المصرية<span className="block text-[10px] tracking-[.18em] text-[#52604d]">DAR AL-BENAA EGYPT</span></Link><nav className="hidden gap-7 text-sm md:flex">{links.map(([label,href])=><Link key={href} href={href} className="hover:text-[#52604d]">{label}</Link>)}</nav><Link href="/consultation" className="button button-solid hidden text-sm md:inline-flex">اطلب استشارة ←</Link><button aria-label="فتح القائمة" aria-expanded={open} onClick={()=>setOpen(!open)} className="md:hidden text-2xl">{open ? "×" : "☰"}</button></div>{open&&<nav className="absolute inset-x-0 top-full min-h-screen bg-[#20231f] p-8 text-[#f4f1ea] md:hidden">{[...links,["اطلب استشارة","/consultation"] as const].map(([label,href])=><Link key={href} href={href} onClick={()=>setOpen(false)} className="block border-b border-white/20 py-6 text-4xl font-serif">{label}</Link>)}</nav>}</header> }
